const menu=document.querySelector('.menu');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));document.querySelector('nav').classList.toggle('open',open)});document.querySelectorAll('nav a').forEach(a=>{if(a.pathname===location.pathname)a.setAttribute('aria-current','page')});const dialog=document.querySelector('#lightbox');document.querySelectorAll('[data-photo]').forEach(b=>b.addEventListener('click',()=>{dialog.querySelector('img').src=b.dataset.photo;dialog.showModal()}));dialog.querySelector('button').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});
// Optional supplied cinematic footage. No media is fetched until an asset is configured.
window.initCinematicIntro=function({desktop,mobile,poster}={}){if(!desktop||sessionStorage.getItem('introSeen')||matchMedia('(prefers-reduced-motion: reduce)').matches||navigator.connection?.saveData)return;const wrap=document.createElement('div');wrap.style.cssText='position:fixed;inset:0;z-index:20;background:#101210';const v=document.createElement('video');v.muted=true;v.playsInline=true;v.autoplay=true;v.poster=poster||'/assets/truck.png';v.style.cssText='width:100%;height:100%;object-fit:cover';v.src=innerWidth<760&&mobile?mobile:desktop;const skip=document.createElement('button');skip.textContent='SKIP INTRO';skip.style.cssText='position:absolute;top:25px;right:25px;padding:15px;background:#151711;color:white;border:1px solid #aaa';const call=document.createElement('a');call.href='tel:+19515635727';call.textContent='CALL (951) 563-5727';call.style.cssText='position:absolute;bottom:30px;left:30px;padding:18px;background:#f4bd28;color:#111';const sound=skip.cloneNode();sound.textContent='SOUND OFF';sound.style.right='155px';sound.onclick=()=>{v.muted=!v.muted;sound.textContent=v.muted?'SOUND OFF':'SOUND ON'};let timer;function finish(){clearTimeout(timer);v.pause();wrap.remove();sessionStorage.setItem('introSeen','1')}skip.onclick=finish;v.onended=finish;v.onerror=finish;wrap.append(v,skip,sound,call);document.body.append(wrap);timer=setTimeout(finish,12000);v.play().catch(finish)};
function photographicEntrance(force=false){if(location.pathname!=='/'||matchMedia('(prefers-reduced-motion: reduce)').matches||navigator.connection?.saveData||(!force&&sessionStorage.getItem('davidsIntroSeen')))return;document.querySelector('.intro')?.remove();const previous=document.activeElement;const intro=document.createElement('section');intro.className='intro';intro.setAttribute('aria-label','David’s Tows photographic introduction');intro.innerHTML=`<div class="intro-frame" style="background-image:url('/assets/night.png')"></div><div class="intro-frame" style="background-image:url('/assets/towing.png');background-position:center 48%"></div><div class="intro-frame" style="background-image:url('/assets/truck.png');background-position:center 58%"></div><div class="intro-shade"></div><img class="intro-logo" src="/assets/logo-clean.svg" alt="David’s Tows"><div class="intro-controls"><button type="button">SKIP INTRO</button></div><div class="intro-copy"><span class="eyebrow">INLAND EMPIRE / 24 HOUR SERVICE</span><h2>READY FOR<br><em>THE NEXT CALL.</em></h2></div><a class="button intro-call" href="tel:+19515635727">CALL (951) 563-5727</a><div class="intro-progress"></div>`;let done=false,timer,cleanup;const finish=()=>{if(done)return;done=true;clearTimeout(timer);sessionStorage.setItem('davidsIntroSeen','1');intro.classList.add('leaving');cleanup=setTimeout(()=>{intro.remove();if(force&&previous?.isConnected)previous.focus()},650)};intro.querySelector('button').onclick=finish;intro.addEventListener('keydown',e=>{if(e.key==='Escape')finish();if(e.key==='Tab'){const controls=[...intro.querySelectorAll('button,a')];if(e.shiftKey&&document.activeElement===controls[0]){e.preventDefault();controls.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===controls.at(-1)){e.preventDefault();controls[0].focus()}}});document.body.append(intro);intro.querySelector('button').focus({preventScroll:true});timer=setTimeout(finish,4600);}
if(location.pathname==='/'){const replay=document.createElement('button');replay.className='replay';replay.textContent='REPLAY ENTRANCE';replay.onclick=()=>photographicEntrance(true);document.querySelector('.herocopy').append(replay);photographicEntrance();}
